# ── PDF hajm rejimi ─────────────────────────────────────────────────────────
# True  = fontlarni PDF ga EMBED QILMAYMIZ → eng kichik hajm (~15–40 KB, martdagidek).
#         PDF faqat onlayn saqlash/ulashish uchun; chop etish Word'dan qilinadi.
#         Windows kompyuterlarda Times New Roman tizimdan olinadi — ko'rinish to'g'ri.
#         Kamchilik: Times New Roman o'rnatilmagan qurilmada (ba'zi telefonlar) shrift
#         almashadi va "10⁹/L" dagi yuqori indeks ⁹ chiqmasligi mumkin.
# False = fontlarni subset qilib EMBED qilamiz → ~42–90 KB, HAR qurilmada bir xil ko'rinadi
#         (QR orqali telefonda ochilsa ham to'g'ri). Kerak bo'lsa shu qiymatni False qiling.
PDF_STRIP_FONTS = True

def load_blanka_config() -> dict:
    default_path = r"G:\DASTUR\URIT 50\Standart shablonlar\blanka ustuni.docx"
    default_config = {
        "blanka_ustuni_path": default_path,
        "logo_path": LOGO_DEFAULT_PATH,
        "header_type": "shablon",
        "klinika_nomi": "AZIZ MEDLINE",
        "klinika_sub": "xususiy laboratoriyasi",
        "klinika_manzil": "Surxondaryo vil., Sherobod tumani, Qo'rg'on MFY,\nY. Oxunboboev ko'chasi, 57E-uy",
        "klinika_tel": "Tel.: (998) 99-673-13-42",
        "logo_width": 3.2,
        "logo_height": 3.2,
        "chap_panel": "barcode",
        "ong_panel": "logo",
        "header_bg_color": "2E75B6",
        "klinika_rang": "1E9943",
        "bemor_row_color": "E6E6E6",
        "table_header_bg": "9DC3E6",
        "group_title_color": "27AE60",
        "qr_link_template": "",
        # Saqlash yo'llari — bo'sh bo'lsa standart yo'l ishlatiladi (pastdagi
        # get_save_dir / _get_onedrive_natijalar ga qarang). Boshqa kompyuterda
        # boshqacha bo'lishi mumkin, shuning uchun Blanka Sozlamalaridan sozlanadi.
        "word_save_dir": "",   # bo'sh = G:\Қилинган анализлар
        "pdf_save_dir": "",    # bo'sh = OneDrive\Natijalar
    }
    if os.path.exists(CONFIG_FILE):
        try:
            with open(CONFIG_FILE, 'r', encoding='utf-8') as f:
                config = json.load(f)
                if isinstance(config, dict):
                    for key, val in default_config.items():
                        if key not in config:
                            config[key] = val
                    return config
                return default_config
        except Exception as e:
            print(f"[OGOHLANTIRISH] Sozlamalarni yuklashda xato: {e}")
            return default_config
    return default_config

def save_blanka_config(config: dict = None):
    if config is None:
        config = {}
    defaults = load_blanka_config()
    for key, val in defaults.items():
        if key not in config:
            config[key] = val
    try:
        with open(CONFIG_FILE, 'w', encoding='utf-8') as f:
            json.dump(config, f, ensure_ascii=False, indent=2)
    except Exception as e:
        print(f"[OGOHLANTIRISH] Sozlamalarni saqlashda xato: {e}")
    # Saqlashdan keyin global blanka ranglarini yangilash
    refresh_blanka_colors()


def get_blanka_printer():
    """Natija blankasi AVTO-pechati uchun ishlatiladigan printer nomini qaytaradi.

    Sozlamalarda (Tizim Sozlamalari → 🖨 Printer) aniq printer tanlangan bo'lsa —
    o'shani qaytaradi. Tanlanmagan bo'lsa yoki tanlangan printer topilmasa —
    Windows'ning standart (asosiy) printeriga o'tadi. Bu tufayli hamshira
    printerni faqat sozlamalardan almashtiradi, kompyuterga tegmasdan."""
    default_printer = None
    try:
        import win32print
        default_printer = win32print.GetDefaultPrinter()
    except Exception:
        pass

    try:
        cfg = load_config()
        name = ((cfg.get("printer", {}) or {}).get("blanka_printer", "") or "").strip()
    except Exception:
        name = ""

    if not name:
        return default_printer

    # Tanlangan printer haqiqatan mavjudmi? Yo'q bo'lsa (masalan tarmoq printeri
    # o'chgan) — standart printerga qaytamiz, chop etish umuman to'xtab qolmasin.
    try:
        import win32print
        flags = win32print.PRINTER_ENUM_LOCAL | win32print.PRINTER_ENUM_CONNECTIONS
        names = {p[2] for p in win32print.EnumPrinters(flags)}
        if name in names:
            return name
        print(f"[OGOHLANTIRISH] Tanlangan printer topilmadi: '{name}' — "
              f"standart printerga ({default_printer}) o'tildi.")
        return default_printer
    except Exception:
        # Tekshirib bo'lmasa — baribir tanlangan nomni ishonib qaytaramiz
        return name

# ----------------------------------------------------------------------------
# BLANKA RANGLARI — config dan yuklanadigan markaziy ranglar (printer siyoh
# balansi uchun sozlanadi). Bu ranglar kod bo'ylab qattiq yozilgan emas — bir
# joydan o'zgartiriladi: "Blanka Sozlamalari → Ranglar" oynasi.
#   TABLE_HEADER_HEX  — jadval ustun sarlavhasi foni (standart ko'k #9DC3E6 → C ko'p)
#   GROUP_TITLE_HEX   — tahlil guruhi sarlavhasi matni (standart yashil #27AE60)
# ----------------------------------------------------------------------------
TABLE_HEADER_HEX = "9DC3E6"
GROUP_TITLE_HEX  = "27AE60"

def refresh_blanka_colors():
    """Global blanka ranglarini config dan qayta yuklash."""
    global TABLE_HEADER_HEX, GROUP_TITLE_HEX
    try:
        cfg = load_blanka_config()
        th = str(cfg.get('table_header_bg', '9DC3E6')).strip().lstrip('#').upper()
        gt = str(cfg.get('group_title_color', '27AE60')).strip().lstrip('#').upper()
        if len(th) == 6:
            TABLE_HEADER_HEX = th
        if len(gt) == 6:
            GROUP_TITLE_HEX = gt
    except Exception as e:
        print(f"[OGOHLANTIRISH] Blanka ranglarini yuklashda xato: {e}")

def _group_title_rgb():
    """Tahlil guruhi sarlavhasi rangini RGBColor sifatida qaytaradi (config dan)."""
    h = GROUP_TITLE_HEX if len(GROUP_TITLE_HEX) == 6 else "27AE60"
    try:
        return RGBColor(int(h[0:2], 16), int(h[2:4], 16), int(h[4:6], 16))
    except Exception:
        return _group_title_rgb()

# Import paytida bir marta yuklab qo'yamiz
refresh_blanka_colors()

