    def show_ginekologik_form(self, test_id, test_name, test_data):
        """
        Ginekologik surtma uchun maxsus jadval formasini ochish.
        Word shabloni o'rniga to'liq Tkinter dialog.
        Natija JSON ga saqlanadi.
        """
        import json
        
        # Eski natijani olish
        old_result = {}
        existing = self.test_results.get(test_id, '')
        if existing and str(existing).strip().startswith('{'):
            try:
                old_result = json.loads(str(existing))
            except:
                old_result = {}
        
        # Dialog oynasi
        dialog = tk.Toplevel(self.root)
        dialog.title(f"Ginekologik Surtma — Natija Kiritish")
        dialog.geometry("750x620")
        dialog.transient(self.root)
        dialog.grab_set()
        dialog.focus_set()
        
        # Sarlavha
        title_label = tk.Label(dialog, text="GINEKOLOGIK SURTMA", 
                               font=("Times New Roman", 14, "bold"), pady=10)
        title_label.pack()
        
        # Jadval maydoni
        table_frame = tk.Frame(dialog, padx=10, pady=5)
        table_frame.pack(fill="both", expand=True)
        
        # Ustun sarlavhalari
        headers = ["Ko'rsatkich", "Qin (V)", "Bachadon bo'yni (C)", "Siydik yo'li (U)"]
        col_widths = [28, 15, 20, 15]
        
        for col, (header, width) in enumerate(zip(headers, col_widths)):
            lbl = tk.Label(table_frame, text=header, font=("Arial", 9, "bold"),
                          relief="groove", width=width, padx=3, pady=5,
                          bg="#d0d0d0", anchor="center")
            lbl.grid(row=0, column=col, sticky="nsew", padx=1, pady=1)
        
        # Jadval qatorlari: (ko'rsatkich_nomi, kalit, turdagi_variantlar)
        rows_config = [
            ("Leykotsitlar",                          "leykot",   "text"),
            ("Yassi epiteliy",                        "yassi",    "text"),
            ("Shilliq",                               "shilliq",  "shilliq"),
            ("Gonokokklar",                           "gonok",    "manfiy"),
            ("Trixomonada",                           "trixom",   "manfiy"),
            ("Atipik (klyucheviy) xujayralar",        "atipik",   "manfiy"),
            ("Laktobatsillalar (tayoqcha\nDoderleyna, gramm musbat tayoqcha)",
                                                  "lakto",    "norma"),
            ("Candida (Aitqi zamburug'i)",            "candida",  "manfiy"),
            ("Anaerob bakteriyalar\n(gramm manfiy tayoqcha), kokklar",
                                                  "anaerob",  "manfiy"),
        ]
        
        # Variantlar lug'ati
        options_map = {
            "manfiy": ["Manfiy (-)", "Musbat (+)"],
            "shilliq": ["-", "+", "++", "+++"],
            "norma":   ["Norma", "Ko'p", "Kam", "Yo'q"],
            "text":    None,  # Entry
        }
        
        # Har bir ustun (V, C, U) uchun widget lar
        entry_vars = {}
        
        columns = ["v", "c", "u"]  # 3 ta ustun kalitlari
        
        for row_idx, (ko_rsatkich, kalit, tur) in enumerate(rows_config, start=1):
            # Ko'rsatkich ustuni
            lbl = tk.Label(table_frame, text=ko_rsatkich, font=("Arial", 9),
                          relief="groove", width=28, padx=3, pady=4,
                          anchor="w", wraplength=200, justify="left")
            lbl.grid(row=row_idx, column=0, sticky="nsew", padx=1, pady=1)
            
            entry_vars[kalit] = {}
            
            for col_idx, col_key in enumerate(columns, start=1):
                key_full = f"{kalit}_{col_key}"
                var = tk.StringVar(value=old_result.get(key_full, ''))
                entry_vars[kalit][col_key] = var
                
                if tur == "text":
                    # Raqam/matn kiritish uchun Entry
                    widget = tk.Entry(table_frame, textvariable=var, 
                                      font=("Arial", 10), width=14, justify="center")
                else:
                    # OptionMenu (dropdown)
                    options = options_map[tur]
                    if not var.get():
                        var.set(options[0])
                    widget = tk.OptionMenu(table_frame, var, *options)
                    widget.config(font=("Arial", 9), width=11)
                
                widget.grid(row=row_idx, column=col_idx, sticky="nsew", padx=1, pady=1)
        
        # Pastki tugmalar
        btn_frame = tk.Frame(dialog, pady=10)
        btn_frame.pack(fill="x")
        
        _saved = [False]  # Ikki marta saqlanishning oldini olish

        def saqlash():
            if _saved[0]:
                return
            _saved[0] = True
            # Tugmani darhol o'chirish (ikki marta bosilishning oldini olish)
            try:
                save_btn.config(state=tk.DISABLED)
            except Exception:
                pass

            result_data = {}
            for kalit, cols in entry_vars.items():
                for col_key, var in cols.items():
                    full_key = f"{kalit}_{col_key}"
                    result_data[full_key] = var.get()

            result_json = json.dumps(result_data, ensure_ascii=False)
            self.test_results[test_id] = result_json
            self._mark_result_pending(test_id, result_json)

            # UI da natijani ko'rsatish (birinchi ustun qiymatlari)
            natija_str = f"v:{result_data.get('leykot_v','')}, c:{result_data.get('leykot_c','')}, u:{result_data.get('leykot_u','')}"

            # Treeview da yangilash
            for tree_item in self.tests_tree.get_children():
                t_data = self.tests_tree.item(tree_item)
                if t_data['tags'] and str(t_data['tags'][0]) == str(test_id):
                    vals = list(t_data['values'])
                    vals[3] = natija_str  # Natija ustuni (index 3)
                    vals[2] = "[OK] Tayyor"  # Status
                    self.tests_tree.item(tree_item, values=vals, tags=('tayyor',))
                    break

            dialog.destroy()
            self.status_var.set(f"Ginekologik surtma natijasi saqlandi")

        def bekor():
            dialog.destroy()

        save_btn = tk.Button(btn_frame, text="Saqlash", command=saqlash,
                  bg="#28a745", fg="white", font=("Arial", 11, "bold"),
                  width=15, pady=5, takefocus=False)
        save_btn.pack(side="left", padx=20)

        tk.Button(btn_frame, text="Bekor", command=bekor,
                  bg="#dc3545", fg="white", font=("Arial", 11),
                  width=12, pady=5, takefocus=False).pack(side="left", padx=5)

        # Enter tugmasi
        dialog.bind('<Return>', lambda e: saqlash())
        dialog.bind('<Escape>', lambda e: bekor())
    
    # ─────────────────────────────────────────────────────────────────────────
    #  YORDAMCHI METOD: JSON natijani saqlash va treeview yangilash
    # ─────────────────────────────────────────────────────────────────────────
    def _save_test_result_to_tree(self, test_id, result_json, natija_str):
        """JSON natijani test_results ga va treeview ga saqlash."""
        self.test_results[test_id] = result_json
        # DB ga hali tushmadi — keyingi load_tests() bazadagi eski qiymat bilan
        # bu natijani bosib ketmasin (tuzatish yo'qolmasin).
        self._mark_result_pending(test_id, result_json)
        for tree_item in self.tests_tree.get_children():
            t_data = self.tests_tree.item(tree_item)
            if t_data['tags'] and str(t_data['tags'][0]) == str(test_id):
                vals = list(t_data['values'])
                vals[3] = natija_str
                vals[2] = "[OK] Tayyor"
                self.tests_tree.item(tree_item, values=vals, tags=('tayyor',))
                break

    # ─────────────────────────────────────────────────────────────────────────
    #  UZI PROTOKOL (vrach qabuli) + MKB-10
    # ─────────────────────────────────────────────────────────────────────────
    def get_mkb10_list(self):
        """MKB-10 kodlari ro'yxatini bazadan oladi ('kod — nomi' ko'rinishida)."""
        try:
            conn = db_conn()
            if not conn:
                return []
            cursor = conn.cursor(dictionary=True)
            cursor.execute("SELECT kod, nomi FROM mkb10 WHERE aktiv=1 ORDER BY kod")
            rows = cursor.fetchall()
            cursor.close()
            conn.close()
            return [f"{r['kod']} — {r['nomi']}" for r in rows]
        except Exception as e:
            print(f"[OGOHLANTIRISH] MKB-10 ro'yxatini olishda xato: {e}")
            return []

    def _uzi_component_frame(self, parent, component, old_components, component_vars):
        """Bitta o'lchov/tanlov maydoni uchun LabelFrame yaratadi (show_template_based_dialog
        bilan bir xil chizish uslubi: options bo'lsa Combobox, bo'lmasa Entry)."""
        comp_key = component.get("key")
        comp_name = component.get("name", comp_key)
        comp_unit = component.get("unit", "")

        comp_frame = ttk.LabelFrame(parent, text=comp_name, padding=6)
        comp_frame.pack(fill="x", pady=3, padx=6)

        old_val = old_components.get(comp_key, "") if isinstance(old_components, dict) else ""
        var = tk.StringVar(value=str(old_val) if old_val is not None else "")
        component_vars[comp_key] = var

        entry_row = ttk.Frame(comp_frame)
        entry_row.pack(fill="x")

        comp_options = component.get("options")
        if comp_options:
            entry = ttk.Combobox(entry_row, textvariable=var, values=comp_options,
                                  state="readonly", font=("Arial", 10))
            entry.pack(side="left", fill="x", expand=True)
            if not var.get():
                var.set(comp_options[0])
        else:
            entry = ttk.Entry(entry_row, textvariable=var, font=("Arial", 10))
            entry.pack(side="left", fill="x", expand=True)

        if comp_unit:
            ttk.Label(entry_row, text=comp_unit, font=("Arial", 9)).pack(side="left", padx=5)

        comp_norma = component.get("norma", "")
        if comp_norma:
            ttk.Label(comp_frame, text=f"Norma: {comp_norma}", font=("Arial", 8),
                      foreground="gray").pack(anchor="w")

    def show_uzi_protokol_form_v2(self, test_id, test_name, test_data):
        """UZI tekshiruvi uchun a'zo-bo'yicha guruhlangan strukturaviy protokol
        (har guruh alohida Notebook tabida) + Xulosa + MKB-10.
        Komponent-ro'yxati tahlillar_norma.result_template dan olinadi — xuddi
        bilirubin/koagulogramma panellarida ishlatiladigan mexanizm (bu yerda
        faqat guruhlash/tablarga bo'lish qo'shilgan)."""
        old_result = {}
        existing = self.test_results.get(test_id, '')
        if existing and str(existing).strip().startswith('{'):
            try:
                old_result = json.loads(str(existing))
            except Exception:
                old_result = {}
        old_components = old_result.get('components', {}) if isinstance(old_result, dict) else {}

        template = self.get_result_template_from_db(test_name)
        components = template.get('components', []) if template else []
        mkb_list = self.get_mkb10_list()

        dialog = tk.Toplevel(self.root)
        dialog.title(f"{test_name} — Protokol")
        dialog.geometry("720x640")
        dialog.transient(self.root)
        dialog.grab_set()
        dialog.focus_set()

        tk.Label(dialog, text=test_name.upper(),
                 font=("Times New Roman", 13, "bold"), pady=8).pack()

        component_vars = {}

        if components:
            nb = ttk.Notebook(dialog)
            nb.pack(fill="both", expand=True, padx=10, pady=(0, 6))
            groups = {}
            for comp in components:
                guruh = comp.get('guruh') or 'Umumiy'
                groups.setdefault(guruh, []).append(comp)
            for guruh, comps in groups.items():
                tab = ttk.Frame(nb)
                nb.add(tab, text=guruh)
                canvas = tk.Canvas(tab, borderwidth=0, highlightthickness=0)
                vscroll = ttk.Scrollbar(tab, orient="vertical", command=canvas.yview)
                canvas.configure(yscrollcommand=vscroll.set)
                vscroll.pack(side="right", fill="y")
                canvas.pack(side="left", fill="both", expand=True)
                inner = ttk.Frame(canvas)
                canvas_window = canvas.create_window((0, 0), window=inner, anchor="nw")
                inner.bind("<Configure>",
                           lambda e, c=canvas: c.configure(scrollregion=c.bbox("all")))
                canvas.bind("<Configure>",
                            lambda e, c=canvas, w=canvas_window: c.itemconfig(w, width=e.width))
                for comp in comps:
                    self._uzi_component_frame(inner, comp, old_components, component_vars)
        else:
            ttk.Label(dialog, text="Bu tekshiruv uchun shablon topilmadi — faqat xulosa kiriting.",
                      foreground="#b71c1c", font=("Arial", 9)).pack(padx=10, pady=(0, 6))

        # Pastki forma: xulosa + MKB-10 (guruh-tablardan tashqarida, doim ko'rinadi)
        bottom_frame = tk.Frame(dialog, padx=10)
        bottom_frame.pack(fill="x")

        tk.Label(bottom_frame, text="Xulosa:", font=("Arial", 10, "bold"), anchor="w").grid(
            row=0, column=0, sticky="w", pady=(4, 2))
        xulosa_var = tk.StringVar(value=old_result.get('xulosa', ''))
        xulosa_entry = tk.Entry(bottom_frame, textvariable=xulosa_var, font=("Arial", 10))
        xulosa_entry.grid(row=1, column=0, columnspan=2, sticky="ew", pady=(0, 8))

        tk.Label(bottom_frame, text="MKB-10 (kodni yozib qidiring):", font=("Arial", 10, "bold"),
                 anchor="w").grid(row=2, column=0, sticky="w", pady=(0, 2))
        mkb_var = tk.StringVar(value=old_result.get('mkb', ''))
        mkb_combo = ttk.Combobox(bottom_frame, textvariable=mkb_var, values=mkb_list,
                                  font=("Arial", 10))
        mkb_combo.grid(row=3, column=0, columnspan=2, sticky="ew", pady=(0, 8))
        bottom_frame.columnconfigure(0, weight=1)

        def _mkb_filter(event=None):
            if event is not None and event.keysym in ("Up", "Down", "Return", "Escape"):
                return
            typed = mkb_var.get().strip().lower()
            mkb_combo['values'] = mkb_list if not typed else [v for v in mkb_list if typed in v.lower()]
        mkb_combo.bind("<KeyRelease>", _mkb_filter)

        btn_frame = tk.Frame(dialog, pady=8)
        btn_frame.pack(fill="x")

        def saqlash():
            xulosa = xulosa_var.get().strip()
            mkb = mkb_var.get().strip()
            mkb_kod = mkb.split(" — ", 1)[0].strip() if " — " in mkb else mkb
            comp_values = {k: v.get().strip() for k, v in component_vars.items()}

            if not any(comp_values.values()) and not xulosa:
                messagebox.showwarning("Ogohlantirish", "Hech qanday ma'lumot yoki xulosa kiritilmagan!")
                return

            data = {
                'components': comp_values,
                'xulosa': xulosa,
                'mkb': mkb,
                'mkb_kod': mkb_kod,
            }
            result_json = json.dumps(data, ensure_ascii=False)
            natija_str = xulosa if xulosa else (f"MKB-10: {mkb_kod}" if mkb_kod else "Protokol kiritildi")
            self._save_test_result_to_tree(test_id, result_json, natija_str)
            dialog.destroy()
            self.status_var.set(f"{test_name} protokoli saqlandi")

        tk.Button(btn_frame, text="Saqlash", command=saqlash,
                  bg="#28a745", fg="white", font=("Arial", 11, "bold"),
                  width=15, pady=5).pack(side="left", padx=20)
        tk.Button(btn_frame, text="Bekor", command=dialog.destroy,
                  bg="#dc3545", fg="white", font=("Arial", 11),
                  width=12, pady=5).pack(side="left")
        dialog.bind('<Escape>', lambda e: dialog.destroy())

